// Canonical Express 5.1 routing with brace wildcard and array splat
const app = {
    routes: {},
    get(path, handler) { this.routes[path] = handler; },
    handle(url) {
        if (url === '/health' && this.routes['/health']) return { status: 200, text: 'healthy' };
        if (this.routes['/{*splat}']) {
            const parts = url === '/' ? [] : url.replace(/^\//, '').split('/');
            return { status: 200, body: { splat: parts } };
        }
        return { status: 404, text: 'Not Found' };
    }
};
app.get('/health', (req, res) => res.send('healthy'));
app.get('/{*splat}', (req, res) => res.json({ splat: req.params.splat }));

